//! Presentation effects the OpenRA way (engine/render.json, generated by
//! tools/gen_content_tables.py from OpenRA's rules and weapons): explosions
//! per CreateEffect warhead, muzzle flashes (WithMuzzleOverlay), smoke over
//! badly damaged units (WithDamageOverlay), the working animations of
//! structures and units (WithResupplyAnimation, WithTeslaChargeAnimation,
//! WithSupportPowerActivationAnimation, WithBuildingPlacedAnimation,
//! WithTurretAttackAnimation, WithLandingCraftAnimation,
//! WithDockingAnimation, the V2 launcher's reloading body), paratroopers
//! under their parachute and OpenRA's Tesla zap (TeslaZapRenderable).
//!
//! Everything here is presentation only, like the doors (doors.rs) and the
//! audio event log: the simulation records when things happened (`ActorFx`,
//! ticks plus one, 0 for never) and never reads it back, and none of it is
//! in `state_hash`. Explosions are effects (`world.effects`), which are
//! not hashed either. Where OpenRA picks at random (an explosion out of a
//! warhead's list, the zap's wander) a hash of the event's position and
//! tick picks instead, so every client draws the same.

use crate::instances::{Sink, SpriteRec};
use crate::render::{posed, px, sheared_offset, Pose, SpriteIds};
use crate::rules::{Kind, Rules};
use crate::world::{Effect, EffectKind, World};

/// The engine's presentation data, generated (tools/gen_content_tables.py).
const RENDER_JSON: &str = include_str!("../render.json");

/// Where an impact is, for the ValidTargets of a CreateEffect warhead
/// (tools/gen_content_tables.py IMPACT_BITS).
pub const IMPACT_GROUND: u8 = 1;
pub const IMPACT_WATER: u8 = 2;
pub const IMPACT_AIR: u8 = 4;
pub const IMPACT_SHIP: u8 = 8;

/// Ticks an explosion effect lives: long enough for every original
/// explosion sequence (the audit checks them, apps/game/js/content/audit.js
/// FX_LIMITS); WebRA's own pictures fade out sooner (`webra_explosion`).
pub const EXPLOSION_LIFE: i32 = 48;
/// Ticks a muzzle flash is drawn after a shot (original sequences play once
/// within it; WebRA's flash shows for `WEBRA_MUZZLE_TICKS`).
pub const MUZZLE_LIFE: u32 = 24;
pub const WEBRA_MUZZLE_TICKS: u32 = 3;
/// Ticks WebRA's own damage smoke takes per loop (OpenRA plays its start
/// sequence, then the loop LoopCount times; with the original graphics the
/// client gives those frame counts, `RenderOptions::smoke_frames`).
pub const WEBRA_SMOKE_TICKS: u32 = 20;
/// Most muzzles (armaments with a muzzle sequence) and barrels in all of an actor's muzzles drawn.
pub const MAX_MUZZLES: usize = 4;
pub const MAX_BARRELS: usize = 8;
/// Ticks a working animation played once (charge, launch, placing, recoil,
/// closing doors, leaving the refinery) is reported after it started: the
/// sequence plays once within it and then shows the idle frames.
pub const ACTIVE_ONCE_LIFE: u32 = 100;
/// OpenRA TeslaZap.Duration: ticks the zap is drawn.
pub const ZAP_TICKS: i32 = 2;
/// Effect slots of the art module after the decorations (apps/game/js/art/effects.js EFFECT_SPECIALS).
pub const FX_SMOKE: f32 = 0.0;
pub const FX_ZAP_BRIGHT: f32 = 1.0;
pub const FX_ZAP_DIM: f32 = 2.0;
/// The anti-air missile (OpenRA Image MISSILE: Nike, RedEye, SubMissileAA;
/// `RenderData::sam_missile`), drawn pointing east like the `missile` special.
pub const FX_SAM_MISSILE: f32 = 3.0;
/// The atom bomb rising and falling (OpenRA NukePower MissileImage atomic,
/// sequences `up` and `down`; abilities.rs), drawn as they are, unturned.
pub const FX_NUKE_UP: f32 = 4.0;
pub const FX_NUKE_DOWN: f32 = 5.0;

/// OpenRA's damage states the smoke starts at (WithDamageOverlay.MinimumDamageState).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SmokeFrom {
    /// Below half health (DamageState.Heavy).
    Heavy,
    /// Below a quarter (DamageState.Critical).
    Critical,
}

/// Which working animation a structure's body plays (the active pose).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ActiveKind {
    /// While it repairs or rearms a unit on it (repeating).
    Resupply,
    /// When it fires (the Tesla coil's charge), once.
    Charge,
    /// When its support power is launched (the missile silo), once.
    Launch,
    /// When its owner places a structure (the construction yard), once.
    Placed,
}

/// One CreateEffect warhead of a weapon.
#[derive(Clone, Debug, Default)]
pub struct EffectWarhead {
    /// Explosions it picks from (indexes into `RenderData::explosions`).
    pub explosions: Vec<u16>,
    /// IMPACT_* bits where it shows.
    pub valid: u8,
    pub delay: i32,
}

/// A muzzle flash: weapon, barrels (forward, right, up), on a turret or the body.
#[derive(Clone, Debug, Default)]
pub struct MuzzleInfo {
    pub weapon: usize,
    pub offsets: Vec<[i32; 3]>,
    pub turret: bool,
    pub turret_offset: [i32; 3],
}

/// Presentation facts of an actor type.
#[derive(Clone, Debug, Default)]
pub struct ActorRender {
    pub muzzles: Vec<MuzzleInfo>,
    pub smoke: Option<SmokeFrom>,
    /// WithDamageOverlay.LoopCount: the loop plays `low` up to `high - 1` times
    /// (OpenRA Util.RandomInRange: MersenneTwister.Next(low, high) leaves `high` out).
    pub smoke_loops: (u32, u32),
    pub active: Option<ActiveKind>,
    pub recoil: bool,
    pub reload_body: bool,
    pub landing_craft: bool,
    pub docking: bool,
}

/// engine/render.json resolved against the rules (by weapon and actor names).
#[derive(Clone, Debug, Default)]
pub struct RenderData {
    pub explosions: Vec<String>,
    /// Per weapon of the rules, its effect warheads.
    pub weapons: Vec<Vec<EffectWarhead>>,
    /// Per weapon of the rules: its missiles are OpenRA's MISSILE image
    /// (`FX_SAM_MISSILE`), not the DRAGON rocket of the `missile` special.
    pub sam_missile: Vec<bool>,
    /// Per actor type of the rules.
    pub actors: Vec<ActorRender>,
}

impl RenderData {
    /// Read render.json for `rules`; names it does not know are left out
    /// (a modded map's actors simply have no effects).
    pub fn load(rules: &Rules) -> RenderData {
        let v: serde_json::Value = serde_json::from_str(RENDER_JSON).expect("render.json is valid JSON");
        let explosions: Vec<String> =
            v["explosions"].as_array().map(|a| a.iter().filter_map(|s| s.as_str().map(str::to_string)).collect()).unwrap_or_default();
        let int = |x: &serde_json::Value| x.as_i64().unwrap_or(0) as i32;
        let triple = |x: &serde_json::Value| {
            let a = x.as_array();
            let at = |k: usize| a.and_then(|a| a.get(k)).map_or(0, int);
            [at(0), at(1), at(2)]
        };
        let weapons = rules
            .weapons
            .iter()
            .map(|w| {
                v["weapons"][w.name.as_str()]
                    .as_array()
                    .map(|list| {
                        list.iter()
                            .map(|e| EffectWarhead {
                                explosions: e["explosions"]
                                    .as_array()
                                    .map(|a| {
                                        a.iter()
                                            .filter_map(|k| k.as_u64())
                                            .filter(|&k| (k as usize) < explosions.len())
                                            .map(|k| k as u16)
                                            .collect()
                                    })
                                    .unwrap_or_default(),
                                valid: int(&e["valid"]) as u8,
                                delay: int(&e["delay"]).clamp(0, EXPLOSION_LIFE),
                            })
                            .filter(|e| !e.explosions.is_empty())
                            .collect()
                    })
                    .unwrap_or_default()
            })
            .collect();
        let actors = rules
            .actors
            .iter()
            .map(|a| {
                let e = &v["actors"][a.id.as_str()];
                let muzzles = e["muzzles"]
                    .as_array()
                    .map(|list| {
                        list.iter()
                            .filter_map(|m| {
                                let name = m["weapon"].as_str()?;
                                let weapon = rules.weapons.iter().position(|w| w.name == name)?;
                                let offsets: Vec<[i32; 3]> =
                                    m["offsets"].as_array().map(|o| o.iter().map(triple).collect()).unwrap_or_default();
                                Some(MuzzleInfo {
                                    weapon,
                                    offsets: if offsets.is_empty() { vec![[0, 0, 0]] } else { offsets },
                                    turret: m["turret"].as_bool().unwrap_or(false),
                                    turret_offset: triple(&m["turret_offset"]),
                                })
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                // At most MAX_MUZZLES muzzles and MAX_BARRELS barrels in all (ActorFx keeps one shot per barrel).
                let mut muzzles: Vec<MuzzleInfo> = muzzles;
                muzzles.truncate(MAX_MUZZLES);
                let mut room = MAX_BARRELS;
                for m in muzzles.iter_mut() {
                    m.offsets.truncate(room.max(1));
                    room = room.saturating_sub(m.offsets.len());
                }
                muzzles.retain(|m| !m.offsets.is_empty());
                ActorRender {
                    muzzles,
                    smoke_loops: {
                        let r: Vec<u32> = e["smoke_loops"]
                            .as_array()
                            .map(|a| a.iter().filter_map(|v| v.as_u64()).map(|v| v.min(8) as u32).collect())
                            .unwrap_or_default();
                        match r.as_slice() {
                            [n] => ((*n).max(1), (*n).max(1) + 1),
                            [lo, hi, ..] => ((*lo).max(1), (*hi).max((*lo).max(1) + 1)),
                            _ => (1, 2),
                        }
                    },
                    smoke: match e["damage_smoke"].as_str() {
                        Some("critical") => Some(SmokeFrom::Critical),
                        Some(_) => Some(SmokeFrom::Heavy),
                        None => None,
                    },
                    active: match e["active"].as_str() {
                        Some("resupply") => Some(ActiveKind::Resupply),
                        Some("charge") => Some(ActiveKind::Charge),
                        Some("launch") => Some(ActiveKind::Launch),
                        Some("placed") => Some(ActiveKind::Placed),
                        _ => None,
                    },
                    recoil: e["recoil"].as_bool().unwrap_or(false),
                    reload_body: e["reload_body"].as_bool().unwrap_or(false),
                    landing_craft: e["landing_craft"].as_bool().unwrap_or(false),
                    docking: e["docking"].as_bool().unwrap_or(false),
                }
            })
            .collect();
        let missiles: Vec<&str> = v["missiles"].as_array().map(|a| a.iter().filter_map(|s| s.as_str()).collect()).unwrap_or_default();
        let sam_missile = rules.weapons.iter().map(|w| missiles.contains(&w.name.as_str())).collect();
        RenderData { explosions, weapons, sam_missile, actors }
    }
}

/// When things happened to an actor, for drawing only (ticks plus one, 0 never).
#[derive(Clone, Copy, Debug, Default)]
pub struct ActorFx {
    /// Last shot of any weapon (turret recoil).
    pub fired: u32,
    /// Last shot of every barrel, the barrels of all muzzles in a row
    /// (OpenRA WithMuzzleOverlay keeps one animation per barrel).
    pub barrels: [u32; MAX_BARRELS],
    /// The barrel each muzzle fires from next (OpenRA Armament cycles its LocalOffsets).
    pub next_barrel: [u8; MAX_MUZZLES],
    /// Damage smoke started, and how often its loop plays this time.
    pub smoke: u32,
    pub smoke_loops: u8,
    /// A working animation started (charge, launch, placing, doors opening, docking).
    pub active: u32,
    /// A unit was serviced on this structure (resupply animation).
    pub serviced: u32,
    /// The work ended (doors closing, leaving the refinery).
    pub ended: u32,
    /// A paratrooper jumped.
    pub dropped: u32,
    /// The landing craft's doors are open.
    pub open: bool,
}

/// A presentation hash of an event (OpenRA uses its cosmetic random there).
pub fn fx_hash(a: i32, b: i32, c: u32) -> u32 {
    let mut h = 0x811c_9dc5u32;
    for v in [a as u32, b as u32, c] {
        h ^= v;
        h = h.wrapping_mul(0x0100_0193);
        h ^= h >> 15;
    }
    h
}

/// WebRA's own look of an explosion: (scale at the start, scale at the end, ticks).
pub fn webra_explosion(name: &str) -> (f32, f32, i32) {
    match name {
        "piff" | "piffs" | "water_piff" | "water_piffs" => (0.6, 1.0, 6),
        "nuke" => (0.5, 2.0, 40),
        "building" | "large_napalm" => (0.7, 1.4, 24),
        "self_destruct" | "large_explosion" | "large_splash" | "artillery_explosion" => (0.7, 1.4, 20),
        _ => (0.6, 1.2, 14),
    }
}

/// Ticks since `stamp` (ticks plus one), if it happened.
#[inline]
pub fn age_of(stamp: u32, tick: u32) -> Option<u32> {
    (stamp > 0).then(|| tick.saturating_sub(stamp - 1))
}

impl World {
    fn fx_info(&self, i: usize) -> &ActorRender {
        &self.rules.render.actors[self.actors[i].ty as usize]
    }

    /// Actor `i` fired weapon `w` (combat.rs `fire_on`): its muzzle flash,
    /// barrel by barrel (OpenRA Armament cycles its LocalOffsets), and the
    /// Tesla coil's charge.
    pub(crate) fn note_fire(&mut self, i: usize, w: usize) {
        let now = self.tick + 1;
        let info = &self.rules.render.actors[self.actors[i].ty as usize];
        let charge = info.active == Some(ActiveKind::Charge);
        // The muzzle of this weapon and where its barrels sit in the row of all barrels.
        let mut first = 0;
        let mut muzzle = None;
        for (m, info) in info.muzzles.iter().enumerate() {
            if info.weapon == w {
                muzzle = Some((m, first, info.offsets.len()));
                break;
            }
            first += info.offsets.len();
        }
        let fx = &mut self.actors[i].fx;
        if let Some((m, first, count)) = muzzle {
            let b = (fx.next_barrel[m] as usize) % count.max(1);
            fx.barrels[first + b] = now;
            fx.next_barrel[m] = ((b + 1) % count.max(1)) as u8;
        }
        fx.fired = now;
        if charge {
            fx.active = now;
        }
    }

    /// Actor `i` was damaged (combat.rs `damage_from`): the damage smoke
    /// starts when it is at OpenRA's damage state and not already smoking.
    pub(crate) fn note_damage_fx(&mut self, i: usize) {
        let Some(from) = self.fx_info(i).smoke else { return };
        let (hp, max) = (self.actors[i].hp as i64, self.rules.actors[self.actors[i].ty as usize].hp.max(1) as i64);
        let bad = match from {
            SmokeFrom::Heavy => hp * 2 < max,
            SmokeFrom::Critical => hp * 4 < max,
        };
        let tick = self.tick;
        if !bad || self.smoke_frame(i).is_some() {
            return;
        }
        // OpenRA picks LoopCount with the shared random (Next(low, high), high
        // left out); a hash of the actor and the tick picks it here.
        let (lo, hi) = self.fx_info(i).smoke_loops;
        let a = &self.actors[i];
        let loops = lo + fx_hash(a.x, a.y, tick.wrapping_add(i as u32)) % (hi - lo).max(1);
        let fx = &mut self.actors[i].fx;
        fx.smoke = tick + 1;
        fx.smoke_loops = loops.min(u8::MAX as u32) as u8;
    }

    /// Where actor `i`'s damage smoke is now: Some(frame) while it plays.
    /// With the original graphics the frame of the start and loop frames in
    /// a row (the start once, then the loop `smoke_loops` times, at the
    /// sequence's rate: `RenderOptions::smoke_frames`); with WebRA's art the
    /// ticks since it started, `WEBRA_SMOKE_TICKS` per loop. Presentation
    /// only: what is drawn decides how long it plays.
    pub(crate) fn smoke_frame(&self, i: usize) -> Option<u32> {
        let a = &self.actors[i];
        let age = age_of(a.fx.smoke, self.tick)?;
        let loops = (a.fx.smoke_loops as u32).max(1);
        let slot = (SpriteIds::new(self.rules.actors.len()).fx_base + FX_SMOKE) as u32;
        if self.render_opts.is_original(slot) {
            let (tick_ms, start, looped) = self.render_opts.smoke_frames?;
            let f = age * (1000 / crate::world::TICKS_PER_SECOND) / tick_ms.max(1);
            if f < start {
                return Some(f);
            }
            let r = f - start;
            return (looped > 0 && r < loops * looped).then(|| start + r % looped);
        }
        (age < WEBRA_SMOKE_TICKS * loops).then_some(age)
    }

    /// Structure `b` repaired or rearmed a unit this tick (resupply animation).
    pub(crate) fn note_service(&mut self, b: usize) {
        self.actors[b].fx.serviced = self.tick + 1;
    }

    /// Structure `i` launched its support power (the missile silo, OpenRA
    /// WithSupportPowerActivationAnimation).
    pub(crate) fn note_launch(&mut self, i: usize) {
        if self.fx_info(i).active == Some(ActiveKind::Launch) {
            self.actors[i].fx.active = self.tick + 1;
        }
    }

    /// `player` placed a structure: the construction yard that built it
    /// plays its placement animation (OpenRA WithBuildingPlacedAnimation on
    /// the queue's most likely producer: the first construction yard).
    pub(crate) fn note_placed(&mut self, player: u8) {
        let now = self.tick + 1;
        if let Some(i) = (0..self.actors.len()).find(|&i| {
            let a = &self.actors[i];
            a.alive && a.in_world() && a.owner == player && self.rules.render.actors[a.ty as usize].active == Some(ActiveKind::Placed)
        }) {
            self.actors[i].fx.active = now;
        }
    }

    /// Harvester `i` docked at the refinery (`docked`) or left it.
    pub(crate) fn note_dock(&mut self, i: usize, docked: bool) {
        let now = self.tick + 1;
        let fx = &mut self.actors[i].fx;
        if docked {
            fx.active = now;
        } else {
            fx.ended = now;
        }
    }

    /// Paratrooper `i` jumped (its parachute opens).
    pub(crate) fn note_drop(&mut self, i: usize) {
        self.actors[i].fx.dropped = self.tick + 1;
    }

    /// Once per tick: the landing craft's doors (OpenRA
    /// WithLandingCraftAnimation.ShouldBeOpen: standing still next to open
    /// ground, OpenTerrainTypes Clear, Rough, Road, Ore, Gems, Beach; ore and
    /// gems lie on clear, rough and road cells).
    pub(crate) fn tick_fx(&mut self) {
        let now = self.tick + 1;
        for i in 0..self.actors.len() {
            if !self.actors[i].alive || !self.fx_info(i).landing_craft || !self.actors[i].in_world() {
                continue;
            }
            let open = self.landing_craft_open(i);
            let fx = &mut self.actors[i].fx;
            if open != fx.open {
                fx.open = open;
                if open {
                    fx.active = now;
                } else {
                    fx.ended = now;
                }
            }
        }
    }

    fn landing_craft_open(&self, i: usize) -> bool {
        let a = &self.actors[i];
        if a.x != a.px || a.y != a.py || a.altitude > 0 {
            return false;
        }
        let (cx, cy) = self.cell_of(a.x, a.y);
        (-1..=1).any(|dy| {
            (-1..=1).any(|dx| {
                (dx, dy) != (0, 0)
                    && self.map.contains(cx + dx, cy + dy)
                    && matches!(
                        self.map.terrain[self.map.idx(cx + dx, cy + dy)],
                        crate::map::Terrain::Clear | crate::map::Terrain::Rough | crate::map::Terrain::Road | crate::map::Terrain::Beach
                    )
            })
        })
    }

    /// Where an impact at (x, y) is, for CreateEffect ValidTargets: on an
    /// airborne aircraft, a ship or submarine, open water or the ground.
    pub(crate) fn impact_class(&self, x: i32, y: i32) -> u8 {
        let ci = self.cell_index(x, y);
        let near = |kind: Option<Kind>, airborne: bool| {
            self.units_in_cell(ci).iter().any(|&u| {
                let a = &self.actors[u as usize];
                a.alive
                    && kind.is_none_or(|k| a.kind == k)
                    && (a.altitude > 0) == airborne
                    && crate::math::dist(x, y, a.x, a.y) <= crate::math::CELL / 2
            })
        };
        if near(None, true) {
            return IMPACT_AIR;
        }
        if near(Some(Kind::Ship), false) {
            return IMPACT_SHIP;
        }
        if self.map.terrain[ci] == crate::map::Terrain::Water && self.building_at[ci] == crate::world::NONE {
            return IMPACT_WATER;
        }
        IMPACT_GROUND
    }

    /// Whether actor `i`'s death weapon shows explosions of its own.
    pub(crate) fn has_death_explosions(&self, i: usize) -> bool {
        self.rules.actors[self.actors[i].ty as usize].death_weapon.is_some_and(|w| !self.rules.render.weapons[w].is_empty())
    }

    /// The explosions of weapon `w` landing at (x, y) where `class`
    /// (IMPACT_*) is: one per CreateEffect warhead valid there, picked out
    /// of its list (OpenRA picks at random, here by a hash of the impact).
    /// Returns whether any showed.
    pub(crate) fn spawn_weapon_effects(&mut self, w: usize, x: i32, y: i32, class: u8) -> bool {
        let mut any = false;
        for k in 0..self.rules.render.weapons[w].len() {
            let e = &self.rules.render.weapons[w][k];
            if e.valid & class == 0 {
                continue;
            }
            let pick = e.explosions[fx_hash(x, y, self.tick.wrapping_add(k as u32)) as usize % e.explosions.len()];
            let delay = e.delay.clamp(0, u8::MAX as i32) as u8;
            let life = EXPLOSION_LIFE + delay as i32;
            self.effects.push(Effect { x, y, tx: x, ty: y, kind: EffectKind::Explosion(pick, delay), ttl: life, max: life });
            any = true;
        }
        any
    }

    // ---- Poses ---------------------------------------------------------------------

    /// A structure's working pose (OpenRA's working animations), if it is working now.
    pub(crate) fn fx_building_pose(&self, i: usize, damaged: bool) -> Option<(Pose, u32)> {
        let a = &self.actors[i];
        let kind = self.fx_info(i).active?;
        let pose = if damaged { Pose::DamagedActive } else { Pose::Active };
        match kind {
            // Repeating while a unit is serviced (this tick or the last).
            ActiveKind::Resupply => age_of(a.fx.serviced, self.tick).filter(|&g| g <= 1).map(|_| (pose, 0)),
            ActiveKind::Charge | ActiveKind::Launch | ActiveKind::Placed => {
                age_of(a.fx.active, self.tick).filter(|&g| g < ACTIVE_ONCE_LIFE).map(|g| (pose, g))
            }
        }
    }

    /// A unit's working pose: the V2 launcher reloading, the landing craft's
    /// doors, the harvester docking and leaving, a paratrooper falling.
    pub(crate) fn fx_unit_pose(&self, i: usize) -> Option<(Pose, u32)> {
        let a = &self.actors[i];
        if a.air.parachute {
            return Some((Pose::Parachute, 0));
        }
        let info = self.fx_info(i);
        if info.reload_body && a.reload.iter().any(|&r| r > 0) {
            return Some((Pose::Active, 0));
        }
        if info.landing_craft {
            if a.fx.open {
                return age_of(a.fx.active, self.tick).map(|g| (Pose::Active, g));
            }
            return age_of(a.fx.ended, self.tick).filter(|&g| g < ACTIVE_ONCE_LIFE).map(|g| (Pose::ActiveEnd, g));
        }
        if info.docking {
            if a.harv == crate::world::HarvState::Unloading {
                return age_of(a.fx.active, self.tick).map(|g| (Pose::Dock, g));
            }
            let still = a.x == a.px && a.y == a.py;
            return age_of(a.fx.ended, self.tick).filter(|&g| g < ACTIVE_ONCE_LIFE && still).map(|g| (Pose::ActiveEnd, g));
        }
        None
    }

    /// A turret's recoil pose (OpenRA WithTurretAttackAnimation), after a shot.
    pub(crate) fn fx_turret_pose(&self, i: usize, damaged: bool) -> Option<(Pose, u32)> {
        let a = &self.actors[i];
        if !self.fx_info(i).recoil {
            return None;
        }
        let pose = if damaged { Pose::DamagedActive } else { Pose::Active };
        age_of(a.fx.fired, self.tick).filter(|&g| g < ACTIVE_ONCE_LIFE).map(|g| (pose, g))
    }

    // ---- Drawing -------------------------------------------------------------------

    /// The muzzle flashes of actor `i` drawn at `at` (its interpolated
    /// position): every barrel that fired lately, at OpenRA's barrel offset
    /// turned with the turret (or body), its sequence played once from its
    /// shot (OpenRA WithMuzzleOverlay: one animation per barrel).
    pub(crate) fn push_muzzle(&self, i: usize, at: SpriteRec, lift: f32, sink: &mut Sink, out: &mut Vec<f32>) {
        let a = &self.actors[i];
        let info = self.fx_info(i);
        if info.muzzles.is_empty() || a.fx.fired == 0 {
            return;
        }
        let ids = SpriteIds::new(self.rules.actors.len());
        let slot = ids.muzzle_base as u32 + a.ty as u32;
        let original = self.render_opts.is_original(slot);
        let life = if original { MUZZLE_LIFE } else { WEBRA_MUZZLE_TICKS };
        let mut k = 0;
        for m in &info.muzzles {
            for barrel in &m.offsets {
                let stamp = a.fx.barrels[k];
                k += 1;
                let Some(age) = age_of(stamp, self.tick).filter(|&g| g < life) else { continue };
                let aim = if m.turret { a.turret } else { a.facing };
                // The barrel turns with the turret, the turret sits on the body (OpenRA Armament.MuzzleOffset),
                // both sheared like the actor's art (RenderOptions::ground_shear).
                let g = self.render_opts.ground_shear(a.ty);
                let b = sheared_offset(barrel[0], barrel[1], aim, g);
                let t = if m.turret { sheared_offset(m.turret_offset[0], m.turret_offset[1], a.facing, g) } else { [0.0, 0.0] };
                let up = px(barrel[2] + if m.turret { m.turret_offset[2] } else { 0 });
                let (dx, dy) = (b[0] + t[0], b[1] + t[1] - up - lift);
                let r = at.facing(aim, 0);
                if original {
                    sink.sprite(out, r.look(posed(slot, Pose::Make, age), a.owner as f32, 1.0, 1.0, 0.0).offset(dx, dy));
                } else {
                    let fade = 1.0 - age as f32 / WEBRA_MUZZLE_TICKS as f32;
                    sink.sprite(out, r.look(slot as f32, a.owner as f32, 1.0, fade, 0.0).offset(dx, dy));
                }
            }
        }
    }

    /// The damage smoke over actor `i` (OpenRA WithDamageOverlay: smoke_m start, then its loop).
    pub(crate) fn push_damage_smoke(&self, i: usize, at: SpriteRec, lift: f32, sink: &mut Sink, out: &mut Vec<f32>) {
        let Some(frame) = self.smoke_frame(i) else { return };
        let ids = SpriteIds::new(self.rules.actors.len());
        let slot = (ids.fx_base + FX_SMOKE) as u32;
        if self.render_opts.is_original(slot) {
            sink.sprite(out, at.look(posed(slot, Pose::Idle, frame), 0.0, 1.0, 1.0, 0.0).offset(0.0, -lift));
        } else {
            // WebRA's puff rises and fades once per loop.
            let k = (frame % WEBRA_SMOKE_TICKS) as f32 / WEBRA_SMOKE_TICKS as f32;
            let r = at.look(slot as f32, 0.0, 0.7 + 0.5 * k, 0.8 * (1.0 - k), 0.0);
            sink.sprite(out, r.offset(0.0, -lift - 4.0 - 8.0 * k));
        }
    }

    /// OpenRA's Tesla zap (TeslaZapRenderable) from (x, y) to (tx, ty),
    /// world pixels: two dim and one bright wandering bolt, each stepped
    /// along in 8 pixel steps that show the frame of their direction.
    pub(crate) fn push_tesla_zap(&self, from: [f32; 2], to: [f32; 2], seed: u32, sink: &mut Sink, out: &mut Vec<f32>) {
        let ids = SpriteIds::new(self.rules.actors.len());
        let (bright, dim) = ((ids.fx_base + FX_ZAP_BRIGHT) as u32, (ids.fx_base + FX_ZAP_DIM) as u32);
        let mut rng = seed;
        let mut next = |n: u32| {
            rng = fx_hash(rng as i32, n as i32, 0x5eed);
            rng
        };
        for (slot, zaps) in [(dim, 2), (bright, 1)] {
            for _ in 0..zaps {
                for (x, y, frame) in zap_wandering(from, to, &mut next) {
                    sink.sprite(out, SpriteRec::at(x, y, 64.0).look(posed(slot, Pose::Idle, frame), 0.0, 1.0, 1.0, 0.0));
                }
            }
        }
    }
}

/// OpenRA's TeslaZapRenderable steps: (dx, dy, offset x, offset y, frame).
const ZAP_STEPS: [[i32; 5]; 8] = [
    [8, 8, 4, 4, 0],
    [-8, -8, -4, -4, 0],
    [8, 0, 4, 4, 1],
    [-8, 0, -4, 4, 1],
    [0, 8, 4, 4, 2],
    [0, -8, 4, -4, 2],
    [-8, 8, -4, 4, 3],
    [8, -8, 4, -4, 3],
];

/// WDist.FromPDF(random, 2) / 1024: the mean of two draws in -1..1.
fn pdf2(next: &mut impl FnMut(u32) -> u32) -> f32 {
    let a = (next(1) % 2048) as f32 - 1024.0;
    let b = (next(2) % 2048) as f32 - 1024.0;
    ((a + b) / 2.0).trunc() / 1024.0
}

/// One wandering bolt (TeslaZapRenderable.DrawZapWandering): two or three
/// straight zaps through points pushed off the line by up to a quarter of
/// its length. Sprites as (x, y, frame).
fn zap_wandering(from: [f32; 2], to: [f32; 2], next: &mut impl FnMut(u32) -> u32) -> Vec<(f32, f32, u32)> {
    let d = [to[0] - from[0], to[1] - from[1]];
    let len = (d[0] * d[0] + d[1] * d[1]).sqrt();
    if len < 1.0 {
        return Vec::new();
    }
    let norm = [-d[1] / len, d[0] / len];
    let at = |f: f32, w: f32| [from[0] + f * d[0] + w * len / 4.0 * norm[0], from[1] + f * d[1] + w * len / 4.0 * norm[1]];
    let mut out = Vec::new();
    if !next(0).is_multiple_of(2) {
        let p1 = at(1.0 / 3.0, pdf2(next));
        let p2 = at(2.0 / 3.0, pdf2(next));
        let p1 = zap(from, p1, &mut out);
        let p2 = zap(p1, p2, &mut out);
        zap(p2, to, &mut out);
    } else {
        let p1 = at(0.5, pdf2(next));
        let p1 = zap(from, p1, &mut out);
        zap(p1, to, &mut out);
    }
    out
}

/// One straight zap (TeslaZapRenderable.DrawZap): from `from`, take the 8
/// pixel step that gets closer to `to` and stays nearest the line, until
/// within 5 pixels. Returns where it ended.
fn zap(from: [f32; 2], to: [f32; 2], out: &mut Vec<(f32, f32, u32)>) -> [f32; 2] {
    let q = [-(to[1] - from[1]), to[0] - from[0]];
    let c = -(from[0] * q[0] + from[1] * q[1]);
    let mut z = from;
    let mut count = 0;
    while (to[0] - z[0]).abs() > 5.0 || (to[1] - z[1]).abs() > 5.0 {
        let dist2 = |p: [f32; 2]| (to[0] - p[0]).powi(2) + (to[1] - p[1]).powi(2);
        let here = dist2(z);
        let step = ZAP_STEPS.iter().filter(|t| dist2([z[0] + t[0] as f32, z[1] + t[1] as f32]) < here).min_by(|a, b| {
            let off = |t: &&[i32; 5]| ((z[0] + t[0] as f32) * q[0] + (z[1] + t[1] as f32) * q[1] + c).abs();
            off(a).total_cmp(&off(b))
        });
        let Some(step) = step else { break };
        out.push(((z[0] + step[2] as f32).trunc(), (z[1] + step[3] as f32).trunc(), step[4] as u32));
        z = [z[0] + step[0] as f32, z[1] + step[1] as f32];
        count += 1;
        if count >= 1000 {
            break;
        }
    }
    z
}
